const URL = "https://coolors.co/0c0e27-ec3642-02cfbe";
let COLS = createCols(URL);
const BG_COL = COLS.shift();
const RADIUS_SPAN = 40;
const ARC_SPAN = 10;

let points = [];

function setup() {

	const s = max(windowWidth, windowHeight) * 0.9;
	createCanvas(s, s);
	let radius = max(width, height) * 0.4;
	let radiusSpan = RADIUS_SPAN;
	let rad = 0;
	const arcSpan = ARC_SPAN;

	let _wG_1 = 0; while ((radius > arcSpan) && ++_wG_1 < 20000)
	{
		const x = cos(rad) * radius;
		const y = sin(rad) * radius;
		const radSpan = (arcSpan / (radius * TAU)) * TAU;
		points.push(createVector(x, y));
		rad += radSpan;
		radius -= radSpan / TAU * radiusSpan;
	}


}

function draw() {
	background(0);
	fill(BG_COL);
	rect(0, 0, width, height);

	const cycle = 30;
	const cycleNum = floor(frameCount / cycle);
	const frameRatio = (frameCount % cycle) / cycle;
	const unitSize = RADIUS_SPAN * 0.92;
	const unitIndexSpan = int(unitSize * 1.2 / ARC_SPAN);
	const colorIndexOffset = int(cycleNum) % COLS.length;

	noFill();
	stroke(0);

	push();
	translate(width / 2, height / 2);

	noStroke();
	rectMode(CENTER);

	//firstObj
	const colIndex = (colorIndexOffset + 1) % COLS.length;
	const start = createVector(points[0].x, -height /2);
	const end = createVector(points[0].x, points[0].y);
	const bounceRatio = easingEaseOutBounce(frameRatio);
	const x = lerp(start.x, end.x, bounceRatio);
	const y = lerp(start.y, end.y, bounceRatio);
	fill(COLS[colIndex]);
	rect(x, y, unitSize, unitSize);

	//
	let count = 0;
	for(let i = 0; i < points.length - unitIndexSpan; i+= (Math.max(0.001, Math.abs(unitIndexSpan)) || 1))
	{
		const indexOffset = floor(frameRatio * unitIndexSpan);
		const startI = i + indexOffset;
		const endI = startI + 1;

		const ratio = (frameRatio * unitIndexSpan) % 1;
		const circleRatio = map(i, 0, points.length - unitIndexSpan, 0, 1, false);
		const x = lerp(points[startI].x, points[endI].x, ratio);
		const y = lerp(points[startI].y, points[endI].y, ratio);
		const dir = atan2(points[endI].y - points[startI].y, points[endI].x - points[startI].x);
		let size = unitSize;
		if(i  > points.length - (unitSize * 1.2 / ARC_SPAN) * 2){
			size *= 1 - easingEaseOutCubic(frameRatio);
		}

		const colIndex = (colorIndexOffset + count) % COLS.length;

		push();
		translate(x, y);
		rotate(dir);

		fill(COLS[colIndex]);
		rect(0, 0, size, size, size * 0.5 * circleRatio);
		pop();
		count++;
	}
	pop();
}


function easingEaseInCubic (x) {
	return pow(x,3);
}

function easingEaseOutCubic (x) {
	return pow(x-1,3) + 1;
}

function easingEaseInOutCubic (x) {
	if(x < 0.5)return 0.5 * pow(2*x, 3);
	else return 0.5 * pow(2*(x-1), 3) + 1;
}

//Bounce
function easingEaseInBounce(x) {
return 1 - easingEaseOutBounce(1 - x);
}

function easingEaseOutBounce(x){
const n1 = 7.5625;
const d1 = 2.75;

if (x < 1 / d1) {
    return n1 * x * x;
} else if (x < 2 / d1) {
    return n1 * (x -= 1.5 / d1) * x + 0.75;
} else if (x < 2.5 / d1) {
    return n1 * (x -= 2.25 / d1) * x + 0.9375;
} else {
    return n1 * (x -= 2.625 / d1) * x + 0.984375;
}
}

function easingEaseInOutBounce(x) {
return x < 0.5 ? (1 - easingEaseOutBounce(1 - 2 * x)) / 2 : (1 + easingEaseOutBounce(2 * x - 1)) / 2;
}


function createCols(url)
{
	let slaIndex = url.lastIndexOf("/");
	let colStr = url.slice(slaIndex +1);
	let cols = colStr.split("-");
	for(let i = 0; i < cols.length; i++)cols[i] = "#" + cols[i];
	return cols;
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
